import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

export default function Page() {
  const data = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense
        fallback={
          <div className="grid grid-cols-2 gap-4">
            <div className="card">
              <h2>Total Revenue</h2>
            </div>
            <div className="card">
              <h2>Total Invoices</h2>
            </div>
          </div>
        }
      >
        <DashboardCards data={data} />
      </Suspense>
      <Suspense
        fallback={
          <div className="chart">
            <h2>Revenue</h2>
          </div>
        }
      >
        <DashboardRevenue data={data} />
      </Suspense>
      <Suspense
        fallback={
          <div className="invoices">
            <h2>Latest Invoices</h2>
          </div>
        }
      >
        <DashboardInvoices data={data} />
      </Suspense>
    </main>
  )
}

async function DashboardCards({ data }: { data: Promise<DashboardData> }) {
  const { totalRevenue, totalInvoices } = await data
  return <CardStats totalRevenue={totalRevenue} totalInvoices={totalInvoices} />
}

async function DashboardRevenue({ data }: { data: Promise<DashboardData> }) {
  const { revenue } = await data
  return <RevenueChart revenue={revenue} />
}

async function DashboardInvoices({ data }: { data: Promise<DashboardData> }) {
  const { invoices } = await data
  return <LatestInvoices invoices={invoices} />
}
